const generateInitialAttendanceSessions = (): AttendanceSession[] => {
  const sessions: AttendanceSession[] = [];
  const studentsList = [
    { id: 'stu-1', name: 'Demo Student', enrollmentNo: '230101001' },
    { id: 'stu-2', name: 'Rohan Verma', enrollmentNo: '230101002' },
    { id: 'stu-3', name: 'Priya Sharma', enrollmentNo: '230101003' },
    { id: 'stu-4', name: 'Amit Patel', enrollmentNo: '230101004' },
    { id: 'stu-5', name: 'Aarav M. Mehta', enrollmentNo: '230101005' },
    { id: 'stu-6', name: 'Diya K. Trivedi', enrollmentNo: '230101006' },
    { id: 'stu-7', name: 'Harsh P. Joshi', enrollmentNo: '230101007' },
    { id: 'stu-8', name: 'Kavya S. Solanki', enrollmentNo: '230101008' },
    { id: 'stu-9', name: 'Manav R. Desai', enrollmentNo: '230101009' },
    { id: 'stu-10', name: 'Neha V. Shah', enrollmentNo: '230101010' },
    { id: 'stu-11', name: 'Rishi B. Prajapati', enrollmentNo: '230101011' },
    { id: 'stu-12', name: 'Tanvi G. Patel', enrollmentNo: '230101012' }
  ];

  const getStudentStatus = (studentIdx: number, lectureIdx: number, totalLectures: number): AttendanceStatus => {
    // Deterministic realistic attendance percentage profiles per student:
    // stu 1: 85%, stu 2: 90%, stu 3: 78%, stu 4: 68% (Shortage), stu 5: 92%, stu 6: 88%,
    // stu 7: 71% (Shortage), stu 8: 95%, stu 9: 63% (Critical), stu 10: 84%, stu 11: 79%, stu 12: 91%
    const targetPercentages = [85, 90, 78, 68, 92, 88, 71, 95, 63, 84, 79, 91];
    const targetPct = targetPercentages[studentIdx % targetPercentages.length];
    const threshold = Math.round((targetPct / 100) * totalLectures);
    
    // Hash function based on studentIdx and lectureIdx for realistic dispersion
    const hash = (lectureIdx * 7 + studentIdx * 13) % totalLectures;
    if (hash < threshold) {
      // 5% chance of being LATE
      if ((hash % 9) === 0) return 'LATE';
      return 'PRESENT';
    }
    return 'ABSENT';
  };

  // 1. DBMS (Total 40)
  for (let i = 1; i <= 40; i++) {
    sessions.push({
      id: `att-dbms-${i}`,
      date: `2026-01-${String((i % 28) + 1).padStart(2, '0')}`,
      subjectId: 'sub-dbms',
      divisionId: 'div-cse-4a',
      facultyId: 'fac-1',
      facultyName: 'Demo Faculty 1',
      lectureNo: i,
      topicTaught: `DBMS Lecture Module ${Math.ceil(i / 8)}: Topic ${i}`,
      submittedAt: `2026-01-${String((i % 28) + 1).padStart(2, '0')}T10:00:00Z`,
      status: 'SUBMITTED',
      records: studentsList.map((s, idx) => ({
        studentId: s.id,
        studentName: s.name,
        enrollmentNo: s.enrollmentNo,
        status: getStudentStatus(idx, i, 40),
        remarks: ''
      }))
    });
  }

  // 2. Computer Networks (Total 42)
  for (let i = 1; i <= 42; i++) {
    sessions.push({
      id: `att-cn-${i}`,
      date: `2026-02-${String((i % 28) + 1).padStart(2, '0')}`,
      subjectId: 'sub-cn',
      divisionId: 'div-cse-4a',
      facultyId: 'fac-3',
      facultyName: 'Dr. Aarav Mehta',
      lectureNo: i,
      topicTaught: `Computer Networks Protocol Stack: Lecture ${i}`,
      submittedAt: `2026-02-${String((i % 28) + 1).padStart(2, '0')}T11:00:00Z`,
      status: 'SUBMITTED',
      records: studentsList.map((s, idx) => ({
        studentId: s.id,
        studentName: s.name,
        enrollmentNo: s.enrollmentNo,
        status: getStudentStatus(idx, i, 42),
        remarks: ''
      }))
    });
  }

  // 3. Data Structures & Algorithms (Total 38)
  for (let i = 1; i <= 38; i++) {
    sessions.push({
      id: `att-dsa-${i}`,
      date: `2026-03-${String((i % 28) + 1).padStart(2, '0')}`,
      subjectId: 'sub-dsa',
      divisionId: 'div-cse-4a',
      facultyId: 'fac-2',
      facultyName: 'Demo Faculty 2',
      lectureNo: i,
      topicTaught: `Data Structures & Algorithmic Analysis: Lecture ${i}`,
      submittedAt: `2026-03-${String((i % 28) + 1).padStart(2, '0')}T09:00:00Z`,
      status: 'SUBMITTED',
      records: studentsList.map((s, idx) => ({
        studentId: s.id,
        studentName: s.name,
        enrollmentNo: s.enrollmentNo,
        status: getStudentStatus(idx, i, 38),
        remarks: ''
      }))
    });
  }

  // 4. Modern Web Architecture (Total 40)
  for (let i = 1; i <= 40; i++) {
    sessions.push({
      id: `att-web-${i}`,
      date: `2026-04-${String((i % 28) + 1).padStart(2, '0')}`,
      subjectId: 'sub-webtech',
      divisionId: 'div-cse-4a',
      facultyId: 'fac-1',
      facultyName: 'Demo Faculty 1',
      lectureNo: i,
      topicTaught: `Modern Web Architecture & REST Services: Lecture ${i}`,
      submittedAt: `2026-04-${String((i % 28) + 1).padStart(2, '0')}T14:00:00Z`,
      status: 'SUBMITTED',
      records: studentsList.map((s, idx) => ({
        studentId: s.id,
        studentName: s.name,
        enrollmentNo: s.enrollmentNo,
        status: getStudentStatus(idx, i, 40),
        remarks: ''
      }))
    });
  }

  return sessions;
};

export const initialAttendanceSessions: AttendanceSession[] = generateInitialAttendanceSessions();


